begin;
create function public.leave_vibe(p_vibe uuid,p_member uuid,p_token text) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare m members;begin m:=vm_authorize(p_vibe,p_member,p_token,false);if m.is_admin then raise exception 'admin_must_delete_or_transfer';end if;update members set user_id=null,claimed_at=null,member_token_hash=null,invited_phone_hash=null,invited_phone_last4=null where id=m.id;insert into activity(vibe_id,actor_member_id,actor_name_snapshot,action_type,entity_type,entity_id) values(p_vibe,m.id,m.display_name,'member_left','member',m.id);end$$;
revoke all on function public.leave_vibe(uuid,uuid,text) from public,anon;grant execute on function public.leave_vibe(uuid,uuid,text) to authenticated;
create function public.delete_vibe_permanently(p_vibe uuid,p_actor uuid,p_token text) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare a members;begin a:=vm_authorize(p_vibe,p_actor,p_token,true);update vibes set admin_member_id=null where id=p_vibe;delete from expense_versions where vibe_id=p_vibe;delete from expense_splits where expense_id in(select id from expenses where vibe_id=p_vibe);delete from settlements where vibe_id=p_vibe;delete from expenses where vibe_id=p_vibe;delete from activity where vibe_id=p_vibe;delete from invites where vibe_id=p_vibe;update members set created_by_member_id=null where vibe_id=p_vibe;delete from members where vibe_id=p_vibe;delete from vibes where id=p_vibe;end$$;
revoke all on function public.delete_vibe_permanently(uuid,uuid,text) from public,anon;grant execute on function public.delete_vibe_permanently(uuid,uuid,text) to authenticated;
commit;
